INSERT INTO dbo.[Notes] ([Note_ID], [ObjectId], [ObjectType], [Notetext], [CreatedAt], [CreatedBy], [UpdatedAt], [UpdatedBy]) VALUES
(1, 84, N'Associate', N'Called Jacqui Francis (RBS) re: role on hold since February. Still paused, but they''re keeping our relationship warm. Sending her a market update next month.', '2022-08-15T10:30:00', 4, '2022-08-15T10:30:00', 18),
(2, 3, N'Req', N'Candidate Tom flagged notice period extended to 8 weeks - outside IR35 rate now £550/day min. Updated brief with client.', '2022-08-15T10:30:00', 18, '2022-08-15T10:30:00', 18),
(3, 211, N'Req', N'Called Ben (candidate) - interviewed at Barclays yesterday, awaiting formal feedback. He felt technical test was challenging.', '2022-08-15T10:30:00', 9, '2022-08-15T10:30:00', 23),
(4, 59, N'Associate', N'Candidate Michael Foster declined the role — preferred another offer. Noted: salary expectations now £700+/day (was £600). Updated his profile.', '2022-08-15T10:30:00', 5, '2022-08-15T10:30:00', 30),
(5, 6, N'Req', N'Chased Finance Director at RBS on payment - invoice #INV-2024-0847 now 45 days overdue. Payment promised by Friday.', '2022-08-15T10:30:00', 25, '2022-08-15T10:30:00', 2),
(6, 196, N'Associate', N'Met with Anita Gupta (Standard Chartered) — renewed PSL contract for another 2 years. Rate card agreed. New contract rates effective 1st May.', '2022-08-15T10:30:00', 13, '2022-08-15T10:30:00', 16),
(7, 11, N'Associate', N'Email to Tariq Hussain (Rolls-Royce) — revised brief received for manufacturing engineer role. Salary now £55k (was £48k), role upgraded to senior level.', '2022-08-15T10:30:00', 23, '2022-08-15T10:30:00', 27),
(8, 113, N'Account', N'Spoke with Amelia (candidate) — she''s received a counter-offer from her current firm. She wants until Friday to decide. Holding the permanent role offer open.', '2022-08-15T10:30:00', 19, '2022-08-15T10:30:00', 6),
(9, 211, N'Req', N'Called Sarah at Barclays - shortlist of 3 CVs sent yesterday, she''s reviewing today. Feedback by EOD tomorrow expected.', '2022-08-15T10:30:00', 16, '2022-08-15T10:30:00', 22),
(10, 87, N'Account', N'Spoke with Marcus at Lloyds — budget confirmed for 4 contractors across Q2/Q3. Rates agreed at £550-650/day depending on seniority. Briefs coming Friday.', '2022-08-15T10:30:00', 29, '2022-08-15T10:30:00', 12),
(11, 91, N'Person', N'Met with NHS Digital procurement team re PSL renewal — confirmed we''re on preferred list for H1 2024. New rate card to be signed off by legal.', '2022-08-15T10:30:00', 20, '2022-08-15T10:30:00', 10),
(12, 13, N'Req', N'Call with Dr Patel (NHS Digital hiring manager) - headcount approval came through, 4 analyst roles now live. Briefs being finalised.', '2022-08-15T10:30:00', 4, '2022-08-15T10:30:00', 30),
(13, 165, N'Associate', N'Spoke with Graham Bell (Canary Wharf Group) — payment terms query resolved. They''ll honour the 30-day invoice terms for the new project. Invoice sent yesterday.', '2022-08-15T10:30:00', 23, '2022-08-15T10:30:00', 26),
(14, 182, N'Person', N'Chased Fiona at Barclays re feedback on the Finance Analyst — she''s in meetings all week, back in office 22 Jan. Will try again.', '2022-08-15T10:30:00', 26, '2022-08-15T10:30:00', 16),
(15, 319, N'Person', N'Candidate (Oliver Richardson) received offer from NatWest, £580/day outside IR35. Accepting. On-boarding call scheduled for 12 Feb.', '2022-08-15T10:30:00', 14, '2022-08-15T10:30:00', 6),
(16, 65, N'Account', N'Spoke with Raj (candidate) — originally said 2 weeks notice but HR is blocking him from leaving before 6 April. Confirmed start date with client now 15 April.', '2022-08-15T10:30:00', 17, '2022-08-15T10:30:00', 9),
(17, 251, N'Person', N'Spoke with BAE Systems account manager — new 12-month contract extension signed, 2 additional embedded C++ roles coming next month.', '2022-08-15T10:30:00', 29, '2022-08-15T10:30:00', 6),
(18, 333, N'Person', N'Called Associate at HSBC (Tim Bradshaw) — role on hold pending headcount freeze review. Timeline unclear, will check back in 2 weeks.', '2022-08-15T10:30:00', 23, '2022-08-15T10:30:00', 10),
(19, 115, N'Account', N'Email received from candidate — got another offer from a competitor at £65k vs our £60k permanent role. Trying to negotiate uplift with the client now.', '2022-08-15T10:30:00', 11, '2022-08-15T10:30:00', 2),
(20, 192, N'Account', N'Email to lead contact at Goldman Sachs — their recruiter took 2 of our candidates as direct hires last month. Relationship needs rebuilding, offering them a meet to discuss partnership terms.', '2022-08-15T10:30:00', 22, '2022-08-15T10:30:00', 15),
(21, 171, N'Person', N'Morgan Stanley account — Q4 budget confirmed for 6 roles (3 Python, 2 React, 1 DevOps). Briefs being prepared, will send by COB Thursday.', '2022-08-15T10:30:00', 2, '2022-08-15T10:30:00', 5),
